def solve_triple_count(n, coloring):
    """
    Calculates the number of monochromatic triples (x, y, z) 
    in {1, ..., n}^3 such that x+y+z is divisible by n.
    Coloring: 0 for Red, 1 for Blue.
    """
    count = 0

    # Check all n^3 triples
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            for z in range(1, n + 1):
                # Check condition (ii): x+y+z divisible by n
                if (x + y + z) % n == 0:
                    # Check condition (i): x, y, z are of the same color
                    if coloring[x-1] == coloring[y-1] == coloring[z-1]:
                        count += 1
    return count

# Test Candidates (n=89 to n=93) using ideal balanced coloring:
# Alternating coloring: R = {1, 3, 5, ...}, B = {2, 4, 6, ...}
# coloring[i] is the color of i+1.
# For n=90: R gets odd numbers (0), B gets even numbers (1)
# For n=89: R gets odd numbers (0), B gets even numbers (1)

def create_alternating_coloring(n):
    # Color 0 = Red, Color 1 = Blue
    coloring = []
    for i in range(1, n + 1):
        # Odd numbers get color 0 (Red), Even numbers get color 1 (Blue)
        coloring.append(i % 2 == 1) 
    return coloring

N_candidates = [89, 90, 91, 92, 93]
results = {}

for n in N_candidates:
    coloring = create_alternating_coloring(n)
    count = solve_triple_count(n, coloring)
    results[n] = count

print("Simulation Results for Balanced Coloring:")
for n, count in results.items():
    print(f"n={n}: Count = {count}")
